const brandNodes = [
  { brand: "Samsung", node: "HTTP Samsung News" },
  { brand: "Xiaomi", node: "HTTP Xiaomi News" },
  { brand: "OPPO", node: "HTTP OPPO News" },
];

const results = [];

for (const entry of brandNodes) {
  const items = $(entry.node).all();

  let articles = [];

  for (const item of items) {
    const data = item.json;
    const news = Array.isArray(data.news) ? data.news : [];

    articles.push(...news);
  }

  // Hapus artikel duplikat berdasarkan URL.
  const uniqueArticles = [
    ...new Map(
      articles.map((article, index) => [
        article.link || `${entry.brand}-${index}`,
        article
      ])
    ).values()
  ];

  results.push({
    brand: entry.brand,
    mentionCount: uniqueArticles.length,
    articles: uniqueArticles.map(article => ({
      title: article.title || "",
      link: article.link || "",
      source: article.source || "",
      date: article.date || "",
      snippet: article.snippet || ""
    }))
  });
}

const totalMentions = results.reduce(
  (sum, item) => sum + item.mentionCount,
  0
);

const output = results.map(item => ({
  brand: item.brand,
  mentionCount: item.mentionCount,
  shareOfVoice: totalMentions > 0
    ? Number(
        (item.mentionCount / totalMentions * 100).toFixed(2)
      )
    : 0,
  articles: item.articles
}));

return [{
  json: {
    generatedAt: new Date().toISOString(),
    totalMentions,
    brands: output
  }
}];

const raw = $input.first().json.text;

let result;

try {
  result = typeof raw === 'string' ? JSON.parse(raw) : raw;
} catch (error) {
  throw new Error(
    'Output Gemini bukan JSON valid. Periksa output Basic LLM Chain.'
  );
}

if (!Array.isArray(result.brands)) {
  throw new Error('Field brands tidak ditemukan atau bukan array.');
}

const requiredBrands = ['Samsung', 'Xiaomi', 'OPPO'];

for (const brand of requiredBrands) {
  const item = result.brands.find(
    b => b.brand?.toLowerCase() === brand.toLowerCase()
  );

  if (!item) {
    throw new Error(`Hasil analisis ${brand} tidak ditemukan.`);
  }

  if (
    !Number.isFinite(item.reputation_score) ||
    item.reputation_score < 1 ||
    item.reputation_score > 10
  ) {
    throw new Error(`Skor reputasi ${brand} tidak valid.`);
  }
}

return [{
  json: {
    brands: result.brands,
    executive_summary: result.executive_summary,
    validation_status: 'passed',
    analyzed_at: new Date().toISOString()
  }
}];

const rows = $('Google Sheet').all().map(item => item.json);

const esc = value => String(value ?? '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;')
  .replace(/'/g, '&#39;');

const scoreColor = score => {
  const n = Number(score);
  if (n >= 7) return '#15803d';
  if (n >= 4) return '#b45309';
  return '#b91c1c';
};

const sentimentLabel = sentiment => {
  const s = String(sentiment ?? '').toLowerCase();
  if (s.includes('positif')) return 'Positif';
  if (s.includes('negatif')) return 'Negatif';
  if (s.includes('netral')) return 'Netral';
  return 'Tidak cukup data';
};

const cards = rows.map(row => `
  <section class="card">
    <div class="card-header">
      <h2>${esc(row.brand)}</h2>
      <span class="sentiment">${esc(sentimentLabel(row.sentiment))}</span>
    </div>
    <div class="score">
      <strong style="color:${scoreColor(row.reputation_score)}">
        ${esc(row.reputation_score)}/10
      </strong>
      <span>Skor Reputasi</span>
    </div>
    <h3>Ringkasan Analisis</h3>
    <p>${esc(row.summary)}</p>
    <h3>Isu yang Ditemukan</h3>
    <p>${esc(row.issues || 'Tidak ada isu spesifik yang tercatat.')}</p>
    <p class="confidence">
      Tingkat keyakinan: <strong>${esc(row.confidence)}</strong>
    </p>
  </section>
`).join('');

const summary = rows[0]?.executive_summary || 'Kesimpulan umum tidak tersedia.';
const analyzedAt = rows[0]?.analyzed_at || new Date().toISOString();

const html = `<!DOCTYPE html>
<html lang="id">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Laporan Analisis Reputasi Smartphone</title>
<style>
  * { box-sizing: border-box; }
  body {
    font-family: Arial, Helvetica, sans-serif;
    color: #1f2937;
    background: #f3f4f6;
    margin: 0;
    padding: 32px;
    line-height: 1.6;
  }
  .report {
    max-width: 900px;
    margin: auto;
    background: white;
    padding: 38px;
    border-radius: 12px;
  }
  .header {
    border-bottom: 3px solid #2563eb;
    padding-bottom: 20px;
    margin-bottom: 28px;
  }
  .eyebrow {
    color: #2563eb;
    font-weight: bold;
    letter-spacing: 1.5px;
    font-size: 12px;
  }
  h1 { font-size: 28px; margin-bottom: 8px; }
  .meta { color: #6b7280; font-size: 13px; }
  .overview {
    background: #eff6ff;
    padding: 20px;
    border-radius: 8px;
    margin-bottom: 26px;
  }
  .cards {
    display: grid;
    grid-template-columns: 1fr;
    gap: 18px;
  }
  .card {
    border: 1px solid #e5e7eb;
    border-radius: 10px;
    padding: 22px;
    page-break-inside: avoid;
    break-inside: avoid;
  }
  .card-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: 12px;
    border-bottom: 1px solid #e5e7eb;
    padding-bottom: 12px;
  }
  h2 { margin: 0; font-size: 21px; }
  h3 { font-size: 14px; margin-bottom: 4px; }
  .sentiment {
    border-radius: 20px;
    padding: 5px 12px;
    background: #f3f4f6;
    font-size: 12px;
    font-weight: bold;
  }
  .score { margin: 18px 0; }
  .score strong { font-size: 34px; }
  .score span { color: #6b7280; margin-left: 8px; }
  .confidence { font-size: 13px; color: #6b7280; }
  footer {
    border-top: 1px solid #e5e7eb;
    margin-top: 30px;
    padding-top: 16px;
    font-size: 11px;
    color: #6b7280;
  }
  @media print {
    body { background: white; padding: 0; }
    .report { padding: 20px; max-width: none; }
  }
</style>
</head>
<body>
<main class="report">
  <header class="header">
    <div class="eyebrow">LAPORAN ANALISIS AI</div>
    <h1>Analisis Sentimen &amp; Reputasi Smartphone</h1>
    <p class="meta">Objek analisis: Samsung, Xiaomi, dan OPPO</p>
    <p class="meta">Waktu analisis: ${esc(analyzedAt)}</p>
  </header>

  <section class="overview">
    <h2>Ringkasan Eksekutif</h2>
    <p>${esc(summary)}</p>
  </section>

  <h2>Hasil Analisis per Merek</h2>
  <div class="cards">${cards}</div>

  <footer>
    Laporan ini dihasilkan secara otomatis melalui workflow n8n
    dengan bantuan Google Gemini. Skor reputasi merupakan estimasi
    berdasarkan data yang tersedia, bukan ukuran reputasi absolut.
    Hasil analisis bergantung pada kualitas dan cakupan data sumber.
  </footer>
</main>
</body>
</html>`;

return [{
  json: {
    report_html: html,
    report_title: 'Analisis Sentimen dan Reputasi Smartphone',
    report_generated_at: new Date().toISOString()
  }
}];

const result = $input.first().json;

return result.brands.map(brand => ({
  json: {
    brand: brand.brand,
    sentiment: brand.sentiment,
    reputation_score: brand.reputation_score,
    issues: Array.isArray(brand.issues)
      ? brand.issues.join('; ')
      : String(brand.issues ?? ''),
    summary: brand.summary,
    confidence: brand.confidence,
    executive_summary: result.executive_summary,
    validation_status: result.validation_status,
    analyzed_at: result.analyzed_at
  }
}));
